// Generates src/i18n.ts from webapp/channels/src/i18n/en.json.
// Run with: npm run i18n:update
// The generated file is committed so the published package is self-contained.

import {readFileSync, writeFileSync} from 'node:fs';
import {resolve, dirname} from 'node:path';
import {fileURLToPath} from 'node:url';

const __dirname = dirname(fileURLToPath(import.meta.url));

const SOURCE = resolve(__dirname, '../../../../webapp/channels/src/i18n/en.json');
const TARGET = resolve(__dirname, '../src/i18n.ts');

const raw = readFileSync(SOURCE, 'utf8');
const entries = JSON.parse(raw);

const lines = [
    '// Copyright (c) 2015-present Mattermost, Inc. All Rights Reserved.',
    '// See LICENSE.txt for license information.',
    '',
    '// Auto-generated by npm run i18n:update',
    '// Source: webapp/channels/src/i18n/en.json',
    '// DO NOT EDIT DIRECTLY — run `npm run i18n:update` to regenerate.',
    '',
    'const en: Record<string, string> = {',
];

for (const [key, value] of Object.entries(entries)) {
    const escapedKey = key.replace(/'/g, "\\'");
    const escapedValue = String(value)
        .replace(/\\/g, '\\\\')
        .replace(/'/g, "\\'")
        .replace(/\n/g, '\\n')
        .replace(/\r/g, '\\r');
    lines.push(`    '${escapedKey}': '${escapedValue}',`);
}

lines.push('};', '', 'export default en;', '');

writeFileSync(TARGET, lines.join('\n'), 'utf8');
console.log(`Generated ${TARGET} with ${Object.keys(entries).length} keys.`);
